@Composable
fun AeonAccountSelection(
    accounts: List<Account>,
    selectedAccountIds: Set<String>,
    onSelectionChange: (Set<String>) -> Unit,
    onDismiss: () -> Unit,
    mode: AeonSelectMode = AeonSelectMode.SINGLE,
    title: String = "Select Account",
    allowOutsideWallet: Boolean = false,
    description: String? = null
) {
    val tertiaryColor = AppColors.tertiary
    val dims = AeonTheme.dimensions

    // Defensive: exclude any synthetic/placeholder accounts with blank ids (e.g. "")
    // from the main list so the explicit "Outside of Wallet" header option does not
    // collide with real data entries that represent the outside transfer placeholder.
    val visibleAccounts = accounts.filter { it.id.isNotBlank() }

    // If there are no real accounts to show but the caller allows selecting
    // an "Outside of Wallet" option, present a compact centered dialog with
    // only that option instead of a full-screen selection sheet.
    if (visibleAccounts.isEmpty() && allowOutsideWallet) {
        Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = true)) {
            val dims = AeonTheme.dimensions
            AeonHazeProvider { hazeLayers ->
                GlassSurface(
                    modifier = Modifier
                        .widthIn(max = 560.dp)
                        .wrapContentHeight()
                        .aeonHazeSource(hazeLayers.states[HazeLayer.Overlay]),
                    shape = RoundedCornerShape(AeonTheme.dimensions.dialogCornerRadius),
                    hazeStyle = GlassTokens.popupStyle(),
                    fallbackColor = AppColors.surfaceContainerHigh,
                    borderColor = AppColors.outlineVariant.copy(alpha = 0.2f),
                    shadowElevation = 6.dp
                ) {
                    Column(modifier = Modifier.padding(dims.cardPadding), verticalArrangement = Arrangement.spacedBy(dims.spacingLg)) {
                        Text(text = title, style = AppTextStyles.cardTitle, color = AppColors.contentPrimary)
                        if (description != null) {
                            Text(text = description, style = AppTextStyles.formFieldNote, color = AppColors.contentSecondary)
                        }

                        AeonHybridSelector(
                            items = listOf(null),
                            mode = mode,
                            selectedIds = if (selectedAccountIds.contains("") ) setOf(null) else emptySet<String?>(),
                            onSelectionChange = {
                                onSelectionChange(setOf(""))
                                if (mode == AeonSelectMode.SINGLE) onDismiss()
                            },
                            idMapper = { null },
                            labelMapper = { "Outside of Wallet" },
                            detailMapper = { "External transfer" },
                            iconMapper = { Icons.Rounded.Public },
                            colorMapper = { tertiaryColor }
                        )

                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                            TextButton(onClick = onDismiss) { Text(stringResource(R.string.action_cancel)) }
                        }
                    }
                }
            }
        }
        return
    }

    AeonSelectionSheet(
        title = title,
        onDismiss = onDismiss,
        items = visibleAccounts,
        selectedIds = selectedAccountIds,
        onSelectionChange = onSelectionChange,
        idMapper = { it.id },
        labelMapper = { it.name },
        mode = mode,
        iconMapper = { getAccountIconByName(it.icon) },
        colorMapper = { Color(android.graphics.Color.parseColor(it.colorHex)) },
        detailMapper = { it.currencyCode },
        searchPlaceholder = "Search accounts...",
        headerContent = {
            if (description != null) {
                Text(
                    text = description,
                    style = AppTextStyles.formFieldNote,
                    color = AppColors.contentSecondary,
                    modifier = Modifier.padding(bottom = dims.spacingSm)
                )
            }

            if (allowOutsideWallet) {
                AeonHybridSelector(
                    items = listOf(null),
                    mode = mode,
                    selectedIds = if (selectedAccountIds.contains("")) setOf(null) else emptySet<String?>(),
                    onSelectionChange = {
                        onSelectionChange(setOf(""))
                        if (mode == AeonSelectMode.SINGLE) onDismiss()
                    },
                    idMapper = { null },
                    labelMapper = { "Outside of Wallet" },
                    detailMapper = { "External transfer" },
                    iconMapper = { Icons.Rounded.Public },
                    colorMapper = { tertiaryColor }
                )
                HorizontalDivider(
                    modifier = Modifier.padding(vertical = dims.spacingSm),
                    thickness = (dims.spacingXs / 8),
                    color = AppColors.outlineVariant
                )
            }
        }
    )
}

@ThemePreviews
@Composable
fun AeonAccountSelectionPreview() {
    OssWalletTheme {
        AeonAccountSelection(
            accounts = listOf(
                Account(
                    id = "1",
                    name = "Savings",
                    colorHex = "#4CAF50",
                    currencyCode = "USD",
                    structureType = AccountStructureType.SAVINGS,
                    icon = "AccountBalance"
                ),
                Account(
                    id = "2",
                    name = "Checking",
                    colorHex = "#2196F3",
                    currencyCode = "USD",
                    structureType = AccountStructureType.BANK,
                    icon = "AccountBalance"
                )
            ),
            selectedAccountIds = setOf("1"),
            onSelectionChange = {},
            onDismiss = {}
        )
    }
}

