val isDarkTheme = when (currentTheme) { "Light" -> false "Dark", "Amoled" -> true else -> isSystemInDarkTheme() } val isAmoled = currentTheme == "Amoled"
when (gridColumns) { 1 -> AeonAccountCardLarge( account = account, balance = balance, balanceInBase = totalInBase, baseCurrency = baseCurrency, currencyBalances = stats?.currencyBalances ?: emptyMap(), incomeInAccountCurrency = stats?.incomeInAccountCurrency ?: BigDecimal.ZERO, expenseInAccountCurrency = stats?.expenseInAccountCurrency ?: BigDecimal.ZERO, isDarkTheme = isDarkTheme, isAmoled = isAmoled, onClick = { onAccountClick(account.id) }, modifier = modifier, onClickIncome = { onRecordsClick?.invoke( filter.copy( accountIds = setOf(account.id), transactionTypes = setOf(TransactionType.INCOME) ) ) }, onClickExpense = { onRecordsClick?.invoke( filter.copy( accountIds = setOf(account.id), transactionTypes = setOf(TransactionType.EXPENSE) ) ) } )
2 -> AeonAccountCardMedium( account = account, balance = balance, balanceInBase = totalInBase, baseCurrency = baseCurrency, currencyBalances = stats?.currencyBalances ?: emptyMap(), isDarkTheme = isDarkTheme, isAmoled = isAmoled, onClick = { onAccountClick(account.id) }, modifier = modifier )
else -> AeonAccountCardSmall( account = account, balance = balance, balanceInBase = totalInBase, baseCurrency = baseCurrency, currencyBalances = stats?.currencyBalances ?: emptyMap(), isDarkTheme = isDarkTheme, isAmoled = isAmoled, onClick = { onAccountClick(account.id) }, modifier = modifier ) } }
