@Composable private fun AeonAddAccountCardContent( baseCurrency: String, currentTheme: String, onClick: () -> Unit, gridColumns: Int = 2, modifier: Modifier = Modifier ) { val isDarkTheme = when (currentTheme) { "Light" -> false "Dark", "Amoled" -> true else -> isSystemInDarkTheme() } val isAmoled = currentTheme == "Amoled" val seedColor = AppColors.primary val placeholderAccount = Account( "empty", "GET STARTED", baseCurrency, AccountStructureType.SAVINGS, String.format("#%06X", 0xFFFFFF and seedColor.toArgb()), "Add", listOf("Add") )
when (gridColumns) { 1 -> AeonAccountCardLarge( account = placeholderAccount, balance = BigDecimal.ZERO, balanceInBase = BigDecimal.ZERO, baseCurrency = baseCurrency, isDarkTheme = isDarkTheme, isAmoled = isAmoled, onClick = onClick, modifier = modifier, extraLabel = "Add New" )
2 -> AeonAccountCardMedium( account = placeholderAccount, balance = BigDecimal.ZERO, balanceInBase = BigDecimal.ZERO, baseCurrency = baseCurrency, isDarkTheme = isDarkTheme, isAmoled = isAmoled, onClick = onClick, modifier = modifier )
else -> AeonAccountCardSmall( account = placeholderAccount, balance = BigDecimal.ZERO, balanceInBase = BigDecimal.ZERO, baseCurrency = baseCurrency, isDarkTheme = isDarkTheme, isAmoled = isAmoled, onClick = onClick, modifier = modifier ) } }
