OssWalletTheme { Box(modifier = Modifier.padding(16.dp)) { AccountsCard( accounts = accounts, accountStats = stats, baseCurrency = "USD", currentTheme = "System", config = AccountsCardConfig(cardId = "preview"), callbacks = CardCallbacks.Accounts(onManageClick = {}, onAccountClick = {}) ) } } }

